-- =====================================================================
-- Online Doctor Appointment System (ODAS)
-- Oracle Database 21c XE Database Schema (Extended SRS Data Model)
-- Compatible with SQL*Plus, SQL Developer, and Oracle 21c XE
-- =====================================================================

-- Drop existing tables in reverse order of foreign key dependencies
BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE PAYMENTS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE PRESCRIPTIONS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE APPOINTMENTS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE DOCTORS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE PATIENTS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE USERS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

-- ---------------------------------------------------------------------
-- 1. USERS TABLE
-- Stores credentials and user roles (PATIENT, DOCTOR, ADMIN)
-- Passwords are stored securely as SHA-256 hashes
-- ---------------------------------------------------------------------
CREATE TABLE USERS (
    ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    USERNAME VARCHAR2(50) NOT NULL,
    PASSWORD VARCHAR2(256) NOT NULL,
    ROLE VARCHAR2(20) NOT NULL,
    CONSTRAINT PK_USERS PRIMARY KEY (ID),
    CONSTRAINT UQ_USERS_USERNAME UNIQUE (USERNAME),
    CONSTRAINT CHK_USERS_ROLE CHECK (ROLE IN ('PATIENT', 'DOCTOR', 'ADMIN'))
);

-- ---------------------------------------------------------------------
-- 2. DOCTORS TABLE
-- Stores medical professional profile information and links to USERS
-- ---------------------------------------------------------------------
CREATE TABLE DOCTORS (
    ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    NAME VARCHAR2(100) NOT NULL,
    SPECIALIZATION VARCHAR2(100) NOT NULL,
    USER_ID NUMBER,
    QUALIFICATION VARCHAR2(100),
    EXPERIENCE NUMBER(3),
    PHONE VARCHAR2(15),
    EMAIL VARCHAR2(100),
    LOCATION VARCHAR2(100),
    AVAILABLE_DAYS VARCHAR2(100),
    AVAILABLE_TIME VARCHAR2(50),
    CONSULTATION_FEE NUMBER(8,2) DEFAULT 500,
    CREATED_DATE TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_DOCTORS PRIMARY KEY (ID),
    CONSTRAINT UQ_DOCTORS_USER UNIQUE (USER_ID),
    CONSTRAINT FK_DOCTORS_USER FOREIGN KEY (USER_ID) REFERENCES USERS(ID) ON DELETE SET NULL
);

-- ---------------------------------------------------------------------
-- 3. PATIENTS TABLE
-- Stores registered patient information and links to USERS
-- ---------------------------------------------------------------------
CREATE TABLE PATIENTS (
    ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    NAME VARCHAR2(100) NOT NULL,
    AGE NUMBER(3) NOT NULL,
    USER_ID NUMBER NOT NULL,
    GENDER VARCHAR2(10),
    PHONE VARCHAR2(15),
    EMAIL VARCHAR2(100),
    ADDRESS VARCHAR2(200),
    CREATED_DATE TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_PATIENTS PRIMARY KEY (ID),
    CONSTRAINT UQ_PATIENTS_USER UNIQUE (USER_ID),
    CONSTRAINT FK_PATIENTS_USER FOREIGN KEY (USER_ID) REFERENCES USERS(ID) ON DELETE CASCADE,
    CONSTRAINT CHK_PATIENTS_AGE CHECK (AGE >= 0 AND AGE <= 130)
);

-- ---------------------------------------------------------------------
-- 4. APPOINTMENTS TABLE
-- Tracks appointments between patients and doctors
-- Active slots enforce uniqueness on (DOCTOR_ID, APPOINTMENT_DATE, APPOINTMENT_TIME)
-- Cancelled appointments are omitted so previously cancelled slots can be rebooked
-- ---------------------------------------------------------------------
CREATE TABLE APPOINTMENTS (
    ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    DOCTOR_ID NUMBER NOT NULL,
    PATIENT_ID NUMBER NOT NULL,
    APPOINTMENT_DATE TIMESTAMP NOT NULL,
    STATUS VARCHAR2(20) DEFAULT 'SCHEDULED' NOT NULL,
    APPOINTMENT_TIME VARCHAR2(20) DEFAULT '10:00' NOT NULL,
    PAYMENT_STATUS VARCHAR2(20) DEFAULT 'UNPAID' NOT NULL,
    REMINDER_SENT NUMBER(1) DEFAULT 0 NOT NULL,
    CONSTRAINT PK_APPOINTMENTS PRIMARY KEY (ID),
    CONSTRAINT FK_APPT_DOCTOR FOREIGN KEY (DOCTOR_ID) REFERENCES DOCTORS(ID),
    CONSTRAINT FK_APPT_PATIENT FOREIGN KEY (PATIENT_ID) REFERENCES PATIENTS(ID),
    CONSTRAINT CHK_APPT_STATUS CHECK (STATUS IN ('SCHEDULED', 'COMPLETED', 'CANCELLED')),
    CONSTRAINT CHK_APPT_PAYMENT CHECK (PAYMENT_STATUS IN ('UNPAID', 'PAID', 'REFUNDED'))
);

-- Migration for existing databases:
-- ALTER TABLE APPOINTMENTS ADD REMINDER_SENT NUMBER(1) DEFAULT 0 NOT NULL;

CREATE UNIQUE INDEX UQ_ACTIVE_APPT_SLOT ON APPOINTMENTS (
    CASE WHEN STATUS <> 'CANCELLED' 
         THEN TO_CHAR(DOCTOR_ID) || '_' || TO_CHAR(APPOINTMENT_DATE, 'YYYY-MM-DD') || '_' || APPOINTMENT_TIME 
         ELSE NULL 
    END
);

-- Constraint (SRS Section 8): Patients cannot book multiple appointments for the same time slot
CREATE UNIQUE INDEX UQ_ACTIVE_PATIENT_SLOT ON APPOINTMENTS (
    CASE WHEN STATUS <> 'CANCELLED' 
         THEN TO_CHAR(PATIENT_ID) || '_' || TO_CHAR(APPOINTMENT_DATE, 'YYYY-MM-DD') || '_' || APPOINTMENT_TIME 
         ELSE NULL 
    END
);

-- ---------------------------------------------------------------------
-- 5. PRESCRIPTIONS TABLE
-- Stores diagnosis and medication details prescribed by doctors
-- ---------------------------------------------------------------------
CREATE TABLE PRESCRIPTIONS (
    ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    APPOINTMENT_ID NUMBER NOT NULL,
    DOCTOR_ID NUMBER NOT NULL,
    PATIENT_ID NUMBER NOT NULL,
    DIAGNOSIS VARCHAR2(500),
    PRESCRIPTION_DETAILS CLOB,
    CREATED_DATE TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_PRESCRIPTIONS PRIMARY KEY (ID),
    CONSTRAINT FK_PRESCRIPTION_APPT FOREIGN KEY (APPOINTMENT_ID) REFERENCES APPOINTMENTS(ID),
    CONSTRAINT FK_PRESCRIPTION_DOCTOR FOREIGN KEY (DOCTOR_ID) REFERENCES DOCTORS(ID),
    CONSTRAINT FK_PRESCRIPTION_PATIENT FOREIGN KEY (PATIENT_ID) REFERENCES PATIENTS(ID),
    CONSTRAINT UQ_PRESCRIPTION_APPT UNIQUE (APPOINTMENT_ID)
);

-- ---------------------------------------------------------------------
-- 6. PAYMENTS TABLE
-- Stores consultation fee payments linked to appointments
-- ---------------------------------------------------------------------
CREATE TABLE PAYMENTS (
    ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    APPOINTMENT_ID NUMBER NOT NULL,
    PATIENT_ID NUMBER NOT NULL,
    AMOUNT NUMBER(10,2) NOT NULL,
    PAYMENT_MODE VARCHAR2(30) NOT NULL,
    PAYMENT_STATUS VARCHAR2(20) DEFAULT 'SUCCESS' NOT NULL,
    PAYMENT_DATE TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_PAYMENTS PRIMARY KEY (ID),
    CONSTRAINT FK_PAYMENT_APPT FOREIGN KEY (APPOINTMENT_ID) REFERENCES APPOINTMENTS(ID),
    CONSTRAINT FK_PAYMENT_PATIENT FOREIGN KEY (PATIENT_ID) REFERENCES PATIENTS(ID),
    CONSTRAINT UQ_PAYMENT_APPT UNIQUE (APPOINTMENT_ID),
    CONSTRAINT CHK_PAYMENT_STATUS CHECK (PAYMENT_STATUS IN ('SUCCESS', 'FAILED', 'PENDING', 'REFUNDED'))
);

